+package main
+
+import (
+	"fmt"
+)
+
+type Field string
+
+const (
+	FieldLine1      Field = "1"
+	FieldLine2      Field = "2"
+	FieldLine3      Field = "3"
+	FieldLocality   Field = "L"
+	FieldRegion     Field = "R"
+	FieldPostalCode Field = "P"
+)
+
+func writeValues(layout string, values map[Field]string) string {
+	var result string
+	prev := 0
+	for i := 0; i < len(layout); i++ {
+		if layout[i] != '%' {
+			continue
+		}
+		j, k := i+1, i+2
+		field := Field(layout[j:k])
+		if values[field] != "" {
+			prefix := layout[prev:i]
+			result += prefix
+			result += values[field]
+		}
+		prev = k
+	}
+	return result
+}
+
+func main() {
+	// Example layout with text after the last token
+	layout := "%L, %P END"
+	values := map[Field]string{
+		FieldLocality:   "City",
+		FieldPostalCode: "12345",
+	}
+	
+	result := writeValues(layout, values)
+	fmt.Printf("Layout: %s\n", layout)
+	fmt.Printf("Result: %s\n", result)
+	fmt.Printf("Expected: City, 12345 END\n")
+}

